export function getUiComponentPreviewMetadata(
  component: string,
): UiComponentPreviewMetadata | undefined {
  return isUiComponentPreviewPath(component)
    ? UI_COMPONENT_PREVIEW_METADATA[component]
    : undefined;
}

function isUiComponentPreviewPath(
  component: string,
): component is keyof typeof UI_COMPONENT_PREVIEW_METADATA {
  return Object.hasOwn(UI_COMPONENT_PREVIEW_METADATA, component);
}
